window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();if(k==='p'&&!e.repeat){pause();return}if(modal.open){if(k==='Escape'&&userStarted&&!['review','morning'].includes(modalContext))close();return}if(['w','a','s','d','q','r','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k))keys.add(k);if(e.repeat)return;if(k==='e')interact();if(k==='f'&&!paused&&!state.ended)phoneMenu();if(k==='c'&&!paused&&!state.ended)toggleCart();if(k==='i')inventoryMenu();if(k==='h')help();if(k==='Escape')pause()});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden&&state)save();lastTime=performance.now()});window.addEventListener('beforeunload',()=>{if(state)save()});
